    const next = { ...(base[ln] || {}) };
    for (const k of Object.keys(block[ln])) {
      const i = k.indexOf(","), r = +k.slice(0, i) + r0, c = +k.slice(i + 1) + c0;
      if (r < 0 || c < 0 || r >= base.rows || c >= base.cols) continue;
      const nk = r + "," + c;
      next[nk] = ln === "fx" ? [...(next[nk] || []), ...block[ln][k]] : block[ln][k];
    }
