          // edge and reappear on the neighbour as a stray mark with nothing feeding it.
          x = Math.max(c * s + jw, Math.min((c + 1) * s - jw, x));
          y = Math.max(r * s + jw, Math.min((r + 1) * s - jw, y));
          d += "L" + px(x) + "," + px(y);
