      for (const [cx, cy] of [[0, 0], [tw, 0], [0, th], [tw, th]]) out += dyeRosette(cx, cy, 26, ring, wob, 5.1);
      out += dyeRosette(tw / 2, th / 2, 30, ring, wob, 41.7);
