            const canStep = (ny) => topdownAt(lv, p.x, ny + ph, pw, CW, CH) && (vdir < 0 || !cellsHit(p.x, ny, pw, ph).some((h) => !curKeys.has(h.r + "," + h.c)));
            if (canStep(p.y + vdir * speed)) { p.y += vdir * speed; tdMove = speed; }
