          // doesn't grab the next tier over. Kills upward velocity — no teleport.
          const centerC = Math.floor((p.x + pw / 2) / CW);
          const ceilRows = ceilingBonkRows(lv, centerC, p.y, ph, p.vy, dtMul, CW, CH);
