          const base = d.base || { w: cur.w, h: cur.h, rot: cur.rot || 0 };
          const raw = { ...cur, w: base.w, h: base.h, rot: base.rot, x: snapPiece(m.x - d.dx), y: snapPiece(m.y - d.dy) };
